from pathlib import Path
import pandas as pd, json, sqlite3, nbformat as nb
from nbclient import NotebookClient
R=Path(__file__).resolve().parents[1]; raw=R/'data/raw'; out=R/'data/processed'; sql=R/'sql'; docs=R/'docs'
keys={'categories':'category_id','products':'product_id','customers':'customer_id','stores':'store_id','warehouses':'warehouse_id','calendar':'day','marketing_channels':'marketing_id','promotions':'promotion_id','orders':'order_id','order_items':'item_id','returns':'return_id','deliveries':'order_id','inventory':'month,warehouse_id,product_id'}
fks={'products':{'category_id':'categories'},'orders':{'day':'calendar','customer_id':'customers','store_id':'stores','warehouse_id':'warehouses','marketing_id':'marketing_channels'},'order_items':{'order_id':'orders','product_id':'products','promotion_id':'promotions'},'returns':{'item_id':'order_items'},'deliveries':{'order_id':'orders'},'inventory':{'warehouse_id':'warehouses','product_id':'products','month':'calendar'}}
con=sqlite3.connect(':memory:'); con.execute('PRAGMA foreign_keys=ON'); schema=[]; dictionary=[]; imports=[]
for t,pk in keys.items():
 path=out/'order_items.csv' if t=='order_items' else raw/f'{t}.csv'; df=pd.read_csv(path); columns=[]
 for c,dt in df.dtypes.items():
  typ='INTEGER' if dt.kind=='i' else 'NUMERIC' if dt.kind=='f' else 'TEXT'; columns.append(f'{c} {typ} NOT NULL'); dictionary.append(f'|{t}|{c}|{typ}|'+('PK ' if c in pk.split(',') else '')+('FK → '+fks[t][c] if c in fks.get(t,{}) else '')+'|')
 
 if t=='inventory':
  columns.extend(['CHECK (stock_start + receipts + emergency_receipts + restocked - sales = stock_end)', 'CHECK (stock_end >= 0 AND stock_start >= 0 AND sales >= 0 AND receipts >= 0 AND emergency_receipts >= 0 AND restocked >= 0 AND unmet_demand >= 0)', 'CHECK (lead_days IN (7,14))']);
 columns.append(f'PRIMARY KEY ({pk})'); columns.extend(f'FOREIGN KEY ({c}) REFERENCES {target}({keys[target]})' for c,target in fks.get(t,{}).items()); ddl=f'CREATE TABLE {t} (\n  '+',\n  '.join(columns)+'\n);'; schema.append(ddl); con.execute(ddl); df.to_sql(t,con,if_exists='append',index=False); imports.append(f"\\copy {t} FROM '{path.relative_to(R)}' CSV HEADER")
(sql/'schema.sql').write_text('\n'.join(schema)); (sql/'import.psql').write_text('\n'.join(imports));
view='''CREATE VIEW sales AS SELECT i.item_id,o.order_id,o.customer_id,o.day,substr(o.day,1,7) AS month, substr(o.day,1,4) AS year,o.channel,s.region,p.category_id,c.category,i.product_id,i.quantity,COALESCE(r.qty,0) AS returned,pr.discount,i.quantity*i.unit_price AS gross,ROUND((i.quantity-COALESCE(r.qty,0))*i.unit_price*(1-pr.discount)+0.000000001,2) AS net,ROUND((i.quantity-COALESCE(r.qty,0))*i.unit_cost,2) AS cogs FROM order_items i JOIN orders o ON i.order_id=o.order_id JOIN products p ON i.product_id=p.product_id JOIN categories c ON p.category_id=c.category_id JOIN promotions pr ON i.promotion_id=pr.promotion_id JOIN stores s ON o.store_id=s.store_id LEFT JOIN (SELECT item_id,SUM(quantity) qty FROM returns GROUP BY item_id) r ON i.item_id=r.item_id WHERE o.status='completed';'''; con.execute(view); (sql/'view.sql').write_text(view)
queries=[('Годовые KPI','SELECT year,SUM(net) net,SUM(net-cogs) profit,COUNT(DISTINCT order_id) orders FROM sales GROUP BY year'),('Маржа категорий','SELECT year,category,SUM(net-cogs)/SUM(net) margin FROM sales GROUP BY year,category'),('Скидки','SELECT year,discount,SUM(net-cogs)/SUM(net) margin FROM sales GROUP BY year,discount'),('Возвраты','SELECT category,1.0*SUM(returned)/SUM(quantity) rate FROM sales GROUP BY category'),('Каналы','SELECT channel,SUM(net) net,SUM(net-cogs) profit FROM sales GROUP BY channel'),('Средний чек','SELECT year,SUM(net)/COUNT(DISTINCT order_id) aov FROM sales GROUP BY year'),('Динамика MoM','WITH m AS (SELECT month,SUM(net) net FROM sales GROUP BY month) SELECT *,net/NULLIF(LAG(net) OVER(ORDER BY month),0)-1 growth FROM m'),('Накопительная выручка','WITH m AS (SELECT month,SUM(net) net FROM sales GROUP BY month) SELECT *,SUM(net) OVER(ORDER BY month) cumulative FROM m'),('Рейтинг SKU','WITH p AS (SELECT product_id,SUM(net) net FROM sales GROUP BY product_id) SELECT *,RANK() OVER(ORDER BY net DESC) ranking FROM p'),('ABC','WITH p AS (SELECT product_id,SUM(net) net FROM sales GROUP BY product_id), a AS (SELECT *, (SUM(net) OVER(ORDER BY net DESC,product_id ROWS UNBOUNDED PRECEDING)-net)/SUM(net) OVER() share FROM p) SELECT *,CASE WHEN share<0.8 THEN \'A\' WHEN share<0.95 THEN \'B\' ELSE \'C\' END class FROM a'),('Повторные клиенты','WITH c AS (SELECT customer_id,COUNT(DISTINCT order_id) n FROM sales GROUP BY customer_id) SELECT AVG(CASE WHEN n>1 THEN 1.0 ELSE 0.0 END) repeat_rate FROM c'),('RFM основа','SELECT customer_id,MAX(day) last_day,COUNT(DISTINCT order_id) frequency,SUM(net) monetary FROM sales GROUP BY customer_id'),('Слабая прибыльность','SELECT product_id,SUM(net) net,SUM(net-cogs) profit FROM sales GROUP BY product_id HAVING SUM(net-cogs)/NULLIF(SUM(net),0)<0.15 ORDER BY net DESC'),('Доставка','SELECT o.channel,AVG(d.delivery_cost) avg_cost,AVG(CASE WHEN actual_days>promised_days THEN 1.0 ELSE 0.0 END) late FROM deliveries d JOIN orders o ON d.order_id=o.order_id GROUP BY o.channel'),('Остатки','SELECT month,warehouse_id,SUM(stock_end) units FROM inventory GROUP BY month,warehouse_id'),('Дефицит','SELECT product_id,SUM(stockout_days) days FROM inventory GROUP BY product_id ORDER BY days DESC'),('Региональная динамика','SELECT year,region,SUM(net) net FROM sales GROUP BY year,region'),('Отмены','SELECT channel,AVG(CASE WHEN status=\'cancelled\' THEN 1.0 ELSE 0.0 END) cancel_rate FROM orders GROUP BY channel'),('Причины возврата','SELECT reason,SUM(quantity) units FROM returns GROUP BY reason'),('Первый заказ','SELECT customer_id,order_id,day FROM (SELECT *,ROW_NUMBER() OVER(PARTITION BY customer_id ORDER BY day,order_id) rn FROM orders WHERE status=\'completed\') q WHERE rn=1'),('Следующая покупка','SELECT customer_id,order_id,day,LEAD(day) OVER(PARTITION BY customer_id ORDER BY day,order_id) next_day FROM orders WHERE status=\'completed\'')]
for j,(name,q) in enumerate(queries,1): pd.read_sql_query(q,con).to_csv(out/f'sql_{j:02}.csv',index=False)
(sql/'analysis.sql').write_text('\n\n'.join(f'-- {j:02}. {name}\n{q};' for j,(name,q) in enumerate(queries,1))); a=pd.read_csv(out/'annual.csv'); b=pd.read_csv(out/'sql_01.csv'); assert (abs(a.net-b.net)<.01).all() and (abs(a.profit-b.profit)<.01).all() and (a.orders==b.orders).all(); assert not con.execute('PRAGMA foreign_key_check').fetchall()
(docs/'data_dictionary.md').write_text('# Словарь данных\n\n|Таблица|Поле|Тип|Ключ|\n|---|---|---|---|\n'+'\n'.join(dictionary)+'\n\nГранулярность: справочники — одна строка на ключ; orders — заказ; order_items — позиция; returns — событие возврата; deliveries — завершённый заказ; inventory — SKU × склад × месяц. Денежные поля в рублях без НДС.\n\n```mermaid\nerDiagram\n'+'\n'.join(f'    {target} ||--o{{ {t} : {c}' for t,fs in fks.items() for c,target in fs.items())+'\n```')
(docs/'sql_guide.md').write_text('# SQL: задачи и результаты\n\n'+'\n\n'.join(f'## {j:02}. {name}\n```sql\n{q}\n```\nРезультат: `data/processed/sql_{j:02}.csv`. Проверено в SQLite. При работе с sales учитывайте гранулярность позиции: заказы считаются DISTINCT, доли — отношением сумм.' for j,(name,q) in enumerate(queries,1)))
# Notebook with executed cells
n=nb.v4.new_notebook(cells=[nb.v4.new_markdown_cell('# Retail Intelligence\nАлександр Артёмов · Синтетическое исследование. Цель: объяснить падение валовой маржи.'),nb.v4.new_code_cell("import pandas as pd\nfrom pathlib import Path\nimport matplotlib.pyplot as plt\nR=Path.cwd()\nf=pd.read_csv(R/'data/processed/sales_fact.csv')\nf.head()"),nb.v4.new_code_cell("raw=pd.read_csv(R/'data/raw/order_items.csv')\nprint('Дубли:',raw.duplicated().sum(),'Пропуски цены:',raw.unit_price.isna().sum())\nassert f.returned.le(f.quantity).all()"),nb.v4.new_code_cell("a=f.groupby('year')[['net','cogs','profit']].sum()\na['margin']=a.profit/a.net\na"),nb.v4.new_code_cell("c=f.groupby(['year','category'])[['net','profit']].sum()\nc['margin']=c.profit/c.net\nc"),nb.v4.new_code_cell("f.groupby('month')[['net','profit']].sum().div(1e6).plot(figsize=(12,4),ylabel='млн ₽');\nplt.show()"),nb.v4.new_code_cell("d=f.groupby(['year','discount'])[['net','profit']].sum()\nd['margin']=d.profit/d.net\nd"),nb.v4.new_markdown_cell('Наблюдаемая связь скидки и маржи частично механическая: скидка уменьшает выручку при неизменной себестоимости. Причинный эффект на спрос не оценен. Данные не являются данными Hoff.')]); NotebookClient(n,timeout=120,kernel_name='python3',resources={'metadata':{'path':str(R)}}).execute(); nb.write(n,R/'Retail_Analysis.ipynb')
